'use strict';

// MODULES //

var Autosize = require( '@stdlib/plot/vega/autosize/ctor' );
var Padding = require( '@stdlib/plot/vega/padding/ctor' );
var Title = require( '@stdlib/plot/vega/title/ctor' );


// MAIN //

/**
* Returns defaults.
*
* @private
* @returns {Object} default options
*
* @example
* var o = defaults();
* // returns {...}
*/
function defaults() {
	return {
		// Schema URL:
		'$schema': 'https://vega.github.io/schema/vega/v6.json',

		// Autosize configuration:
		'autosize': new Autosize(),

		// Coordinate axes:
		'axes': [],

		'background': '',

		// Visualization theme:
		'config': {},

		// Data set definitions and transforms:
		'data': [],

		// Visualization description:
		'description': '',

		// Visual encodings:
		'encode': {},

		// Height (in pixels):
		'height': 0,

		// Legends:
		'legends': [],

		// Graphical marks:
		'marks': [],

		// Padding (in pixels):
		'padding': new Padding(),

		// Cartographic projections:
		'projections': [],

		// Visualization scales:
		'scales': [],

		// Signals for parameterizing a visualization:
		'signals': [],

		// Visualization title:
		'title': new Title(),

		// Optional meta data:
		'usermeta': {},

		// Width (in pixels):
		'width': 0
	};
}


// EXPORTS //

module.exports = defaults;
